begin;
alter table public.fpg_members add column full_process boolean not null default false;
alter table public.fpg_cases add column administrator_review boolean not null default false;
alter table public.fpg_workpapers add column administrator_review boolean not null default false;
alter table public.fpg_cases drop constraint fpg_cases_check;
alter table public.fpg_cases add constraint fpg_cases_check check(reviewed_by is null or reviewed_by<>created_by or administrator_review);
alter table public.fpg_workpapers drop constraint fpg_workpapers_check;
alter table public.fpg_workpapers add constraint fpg_workpapers_check check(reviewed_by is null or reviewed_by<>prepared_by or administrator_review);
create function fpg_private.full_process() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.fpg_members where user_id=auth.uid() and active and role='admin' and full_process)$$;
revoke all on function fpg_private.full_process() from public,anon;
grant execute on function fpg_private.full_process() to authenticated;
update public.fpg_members set role='admin',active=true,full_process=true where user_id='df627f92-e256-47eb-8a92-590ee9cf7d59' and exists(select 1 from auth.users where id=user_id and lower(email)='netsgcwork@gmail.com');
do $$declare d text;before_text text;begin
 select pg_get_functiondef('fpg_private.save_case(jsonb)'::regprocedure) into d;before_text:=d;
 d:=replace(d,'u=c.created_by or length(trim(coalesce(p->>''review_note'','''')))=0','(u=c.created_by and not fpg_private.full_process()) or length(trim(coalesce(p->>''review_note'','''')))=0');
 d:=replace(d,'c.reviewed_by:=u;c.review_note:=p->>''review_note'';', 'c.administrator_review:=(u=c.created_by);c.reviewed_by:=u;c.review_note:=case when c.administrator_review then ''Administrator review (same account): '' else '''' end||(p->>''review_note'');');
 d:=replace(d,'c.reviewed_by:=null;c.review_note:=null;', 'c.administrator_review:=false;c.reviewed_by:=null;c.review_note:=null;');
 d:=replace(d,'reviewed_by=c.reviewed_by,review_note=c.review_note','administrator_review=c.administrator_review,reviewed_by=c.reviewed_by,review_note=c.review_note');
 if d=before_text then raise exception 'Case function did not match';end if;execute d;
 select pg_get_functiondef('fpg_private.prepare_journal(date)'::regprocedure) into d;
 d:=replace(d,'c.reviewed_by=c.created_by','(c.reviewed_by=c.created_by and not c.administrator_review)');execute d;
 select pg_get_functiondef('fpg_private.save_workpaper(jsonb)'::regprocedure) into d;before_text:=d;
 d:=replace(d,'w.prepared_by=auth.uid() or length(trim(coalesce(p->>''review_note'','''')))<5','(w.prepared_by=auth.uid() and not fpg_private.full_process()) or length(trim(coalesce(p->>''review_note'','''')))<5');
 d:=replace(d,'set state=''Reviewed'',reviewed_by=auth.uid(),review_note=p->>''review_note''','set state=''Reviewed'',administrator_review=(w.prepared_by=auth.uid()),reviewed_by=auth.uid(),review_note=case when w.prepared_by=auth.uid() then ''Administrator review (same account): '' else '''' end||(p->>''review_note'')');
 d:=replace(d,'set state=''Returned'',reviewed_by=null','set state=''Returned'',administrator_review=false,reviewed_by=null');
 d:=replace(d,'prepared_by=auth.uid(),reviewed_by=null,version=','prepared_by=auth.uid(),administrator_review=false,reviewed_by=null,version=');
 d:=replace(d,'coalesce(p->>''review_note'',p->>''conclusion'','''')','case when w.administrator_review then ''Administrator review (same account): '' else '''' end||coalesce(p->>''review_note'',p->>''conclusion'','''')');
 if d=before_text then raise exception 'Workpaper function did not match';end if;execute d;
end $$;
commit;
